window.docContents[52].resolve({"/Error-Functions___-Dawson___s-and-Fresnel-Integrals/#chapter-7":{"contents":"The chapter shell reserves the source-facing navigation. LMLF currently has no accepted definition,\nqualitative bridge, or quantitative theorem for these named functions.\n\nThe planned family wave separates object identification from later series, integral, asymptotic, zero,\nand inverse-function results. Scale conventions for Fresnel and Voigt variants must be fixed before\nshared infrastructure is presented as a named theorem.\n\n\n\n","context":"LMLF · Mathematical Functions with Lean","header":"7. Error Functions, Dawson's and Fresnel Integrals","id":"/Error-Functions___-Dawson___s-and-Fresnel-Integrals/#chapter-7"}});